Index: index.html
===================================================================
--- index.html
+++ index.html
@@ -19,4 +19,51 @@
 <aside class="side"><section class="panel quest-panel"><div class="eyebrow" id="chapterLabel">KAPITEL I · WESTEN</div><h2 class="quest-title" id="questTitle">Der grüne Saum</h2><div class="quest-copy" id="questCopy">Die Waldpfade sind von elfischen Spähern besetzt. Räume den Weg zum alten Hain frei.</div><div class="objective" id="objective">Ziel: <strong>Späher besiegen</strong> <span id="objectiveCount">0 / 4</span></div></section><section class="panel"><h2>DEIN WEG</h2><div class="stats"><div class="stat"><span>STUFE</span><b id="levelText">01</b></div><div class="stat"><span>ELFEN BESIEGT</span><b id="killsText">0</b></div></div><div class="roster"><i class="enemy-dot"></i><span id="enemyLabel">Elfische Späher</span></div><div class="legend" id="progressText">Westen befreien: <b>0 / 3 Kapitel</b></div></section></aside></main>
 <footer class="bottom"><span>✦ SPEICHERT AUTOMATISCH AUF DIESEM GERÄT</span><div class="keys"><span class="key">W A S D</span><span class="key">BEWEGEN</span><span class="key">LEERTASTE</span><span class="key">ANGRIFF</span><span class="key">E</span><span class="key">TRUHE</span></div><span>ASH &amp; OAK · 1.0</span></footer>
 </div>
 <script>
+(()=>{
+const canvas=document.getElementById('game'),ctx=canvas.getContext('2d');ctx.imageSmoothingEnabled=false;
+const W=100,H=40,T=16,keys=new Set(),tile=new Uint8Array(W*H),noise=(x,y)=>{let n=x*374761393+y*668265263;n=(n^(n>>13))*1274126177;return((n^(n>>16))>>>0)/4294967295};
+const stages=[
+ {name:'Der grüne Saum',area:'GRÜNHOLZ',side:'WESTEN',enemy:'Elfische Späher',count:4,center:[12,19],copy:'Die Waldpfade sind von elfischen Spähern besetzt. Räume den Weg zum alten Hain frei.'},
+ {name:'Das Mondquell-Verlies',area:'MONDQUELL',side:'WESTEN',enemy:'Elfische Klingenwachen',count:5,center:[28,26],copy:'Unter den silbernen Quellen liegt ein vergessenes Verlies. Die elfischen Wachen halten den Zugang.'},
+ {name:'Die Dornenkrone',area:'DORNENFESTE',side:'WESTEN',enemy:'Hauptmann Vaelis',count:1,boss:true,center:[41,14],copy:'Im Herzen der Festung wartet Vaelis. Besiege den Hauptmann — erst dann ist der Westen frei.'},
+ {name:'Jenseits der Mauer',area:'STEINPASS',side:'OSTEN',enemy:'Passwächter',count:5,center:[61,22],copy:'Der Westen ist befreit. Die Gebirgsmauer ist durchbrochen — sichere den Pass für den Marsch nach Osten.'},
+ {name:'Der Aschenwald',area:'ASCHENWALD',side:'OSTEN',enemy:'Elfische Waldläufer',count:5,center:[77,11],copy:'Im Aschenwald sammeln die Elfen ihre letzten Truppen. Kämpfe dich durch die verkohlten Baumreihen.'},
+ {name:'Der Smaragdthron',area:'SMARAGDTHRON',side:'OSTEN',enemy:'Königin Aelthra',count:1,boss:true,center:[92,25],copy:'Hinter den Toren des Smaragdthrons erwartet dich die Elfenkönigin. Beende den Krieg.'}
+];
+let player={x:8.5,y:19.5,hp:100,max:100,level:1,xp:0,kills:0,face:'down',atk:0,invul:0},stage=0,enemies=[],chestOpen=false,gameStarted=false,gameWon=false,shake=0,cam={x:0,y:0};
+const saved=(()=>{try{return JSON.parse(localStorage.getItem('ash-oak-save')||'null')}catch{return null}})();
+function idx(x,y){return y*W+x}function inBounds(x,y){return x>=0&&y>=0&&x<W&&y<H}
+function makeMap(){for(let y=0;y<H;y++)for(let x=0;x<W;x++){let v=0;
+ if(y<3||y>36||x<2||x>97)v=1;
+ // mountain spine, with a narrow old causeway
+ if(x>=46&&x<=53)v=(y>=17&&y<=21)?0:2;
+ // natural rough terrain / woodland edge
+ if((x<46||x>53)&&noise(x,y)>.91&&!(y>=17&&y<=21&&x>4&&x<95))v=1;
+ // clearings and roads connecting chapter sites
+ const pathY= x<18?19:x<34?24:x<45?17:x<54?19:x<70?22:x<84?12:25;
+ if(Math.abs(y-pathY)<=1&&x>4&&x<96)v=0;
+ for(const [cx,cy,r] of [[12,19,5],[28,24,5],[41,17,5],[61,22,5],[77,12,5],[92,25,5]])if((x-cx)**2+(y-cy)**2<r*r)v=0;
+ tile[idx(x,y)]=v;
+ }
+ // Dedicated stone crossing through mountain
+ for(let x=45;x<=54;x++)for(let y=19;y<=20;y++)tile[idx(x,y)]=0;
+}
+function loadStage(){enemies=[];if(stage>=stages.length)return;const s=stages[stage];let n=s.count;
+ for(let i=0;i<n;i++){let a=(Math.PI*2*i/n)+.35,rad=s.boss?0:2.4+(i%2)*1.1,x=s.center[0]+Math.cos(a)*rad,y=s.center[1]+Math.sin(a)*rad;
+ enemies.push({x,y,hp:s.boss?12:3,max:s.boss?12:3,boss:!!s.boss,hit:0,walk:Math.random()*5});}
+ updateUI();save();}
+function save(){try{localStorage.setItem('ash-oak-save',JSON.stringify({stage,player:{hp:player.hp,level:player.level,xp:player.xp,kills:player.kills},chestOpen,gameWon}))}catch{}}
+if(saved){stage=Math.min(saved.stage||0,stages.length);Object.assign(player,saved.player||{});chestOpen=!!saved.chestOpen;gameWon=!!saved.gameWon;if(stage<stages.length){let [x,y]=stages[stage].center;player.x=x-4;player.y=y+3}else{player.x=92;player.y=29}loadStage();}
+makeMap();if(!saved)loadStage();
+const el=id=>document.getElementById(id);let toastTimer;
+function toast(msg){const t=el('toast');t.textContent=msg;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2100)}
+function updateUI(){const s=stages[Math.min(stage,stages.length-1)];if(!s)return;el('chapterTop').textContent=stage<3?`Kapitel ${['I','II','III'][stage]} · ${s.name}`:`Kapitel ${['IV','V','VI'][stage-3]} · ${s.name}`;el('chapterLabel').textContent=`KAPITEL ${['I','II','III','IV','V','VI'][stage]||'VI'} · ${s.side}`;el('questTitle').textContent=stage>=stages.length?'Der Kontinent ist frei':s.name;el('questCopy').textContent=stage>=stages.length?'Die Elfen haben ihre Waffen niedergelegt. Der Kontinent gehört wieder allen Völkern.':s.copy;el('areaTag').textContent=stage>=stages.length?'FRIEDEN':s.area;el('enemyLabel').textContent=stage>=stages.length?'Keine Feinde':s.enemy;el('objective').innerHTML=stage>=stages.length?'<strong>Abenteuer abgeschlossen</strong> ✦':`Ziel: <strong>${s.boss?'Boss besiegen':s.enemy+' besiegen'}</strong> <span id="objectiveCount">${s.count-enemies.length} / ${s.count}</span>`;el('levelText').textContent=String(player.level).padStart(2,'0');el('killsText').textContent=player.kills;el('progressText').innerHTML=`Westen befreien: <b>${Math.min(stage,3)} / 3 Kapitel</b><br>Gebirgsmauer: <b>${stage>=3?'Pass offen':'Pass versperrt'}</b>`;el('hpText').textContent=`${Math.ceil(player.hp)} / ${player.max}`;el('hpBar').style.width=`${Math.max(0,player.hp)/player.max*100}%`;el('xpText').textContent=`${player.xp} / 100`;el('xpBar').style.width=`${player.xp}%`;}
+function completeStage(){stage++;player.hp=Math.min(player.max,player.hp+30);if(stage>=stages.length){gameWon=true;gameStarted=false;el('modalTitle').textContent='Der Kontinent ist frei';el('modalText').textContent='Die Elfenkönigin hat kapituliert. Die Gebirgsmauer trennt die Völker nicht länger. Danke, dass du den Krieg beendet hast.';el('modal').hidden=false;}else{loadStage();toast(stage===3?'Die Gebirgsmauer ist offen! Der Weg nach Osten ist frei.':`Kapitel abgeschlossen · +30 Leben`);}updateUI();save();}
+function canStand(x,y){let tx=Math.floor(x),ty=Math.floor(y);return inBounds(tx,ty)&&tile[idx(tx,ty)]!==1&&tile[idx(tx,ty)]!==2}
+function tryMove(dx,dy,dt){if(!dx&&!dy)return;const speed=5.1*dt;let nx=player.x+dx*speed,ny=player.y+dy*speed;if(canStand(nx,player.y))player.x=nx;if(canStand(player.x,ny))player.y=ny;if(Math.abs(dx)>Math.abs(dy))player.face=dx>0?'right':'left';else player.face=dy>0?'down':'up';}
+function attack(){if(!gameStarted||player.atk>0)return;player.atk=.34;let dir={up:[0,-1],down:[0,1],left:[-1,0],right:[1,0]}[player.face];let tx=player.x+dir[0]*1.35,ty=player.y+dir[1]*1.35,hit=null,best=2.1;
+ for(const e of enemies){let dx=e.x-tx,dy=e.y-ty,d=Math.hypot(dx,dy);if(d<best&&Math.hypot(e.x-player.x,e.y-player.y)<2.5){best=d;hit=e}}
+ if(hit){hit.hp--;hit.hit=.16;shake=3;if(hit.hp<=0){enemies.splice(enemies.indexOf(hit),1);player.kills++;player.xp+=hit.boss?55:25;if(player.xp>=100){player.level++;player.xp-=100;player.max+=15;player.hp=Math.min(player.max,player.hp+35);toast(`Stufe ${player.level}! Leben +15`)}else toast(hit.boss?'Hauptmann besiegt!':'Elf besiegt');if(enemies.length===0)completeStage();updateUI();save()}else toast('Treffer!');}else toast('Daneben!');}
+function interact(){if(stage===0&&!chestOpen&&Math.hypot(player.x-9,player.y-22)<2.1){chestOpen=true;player.hp=player.max;player.xp=Math.min(99,player.xp+25);toast('Alte Vorratskiste · Leben aufgefüllt');save();return;}if(stage<3&&player.x>45)toast('Die Gebirgsmauer ist noch versperrt. Befreie erst den Westen!');else if(stage>=3&&player.x>45&&player.x<55)toast('Der Pass nach Osten ist offen!');else toast('Hier gibt es nichts zu öffnen.');}
+function showModal(title,text){el('modalTitle').textContent=title;el('modalText').textContent=text;el('modal').hidden=false}function toggleMap(){showModal('Der zerrissene Kontinent',`WESTEN · ${Math.min(stage,3)}/3 Kapitel befreit\n${stage<3?'Grünholz → Mondquell → Dornenfeste':'Der Westen ist frei'}\n\nGEBIRGSMauer · ${stage>=3?'Pass geöffnet':'Übergang versperrt'}\n\nOSTEN · ${Math.max(0,stage-3)}/3 Kapitel befreit\n${stage>=3?'Steinpass → Aschenwald → Smaragdthron':'Wartet hinter der Gebirgsmauer'}`)}

